import uuid
from typing import Any

from sqlalchemy import Dialect
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.types import CHAR, TypeDecorator


class GUID(TypeDecorator):
    """Platform-independent GUID type.
    Uses PostgreSQL's UUID type, otherwise uses
    CHAR(32), storing as stringified hex values.
    """

    impl = CHAR
    cache_ok = True

    @staticmethod
    def generate():
        return uuid.uuid4()

    @staticmethod
    def convert_value_to_guid(value: Any, dialect: Dialect) -> str | None:
        if value is None:
            return value
        elif dialect.name == "postgresql":
            return str(value)
        else:
            if not isinstance(value, uuid.UUID):
                return f"{uuid.UUID(value).int:032x}"
            else:
                # hexstring
                return f"{value.int:032x}"

    def load_dialect_impl(self, dialect):
        if dialect.name == "postgresql":
            return dialect.type_descriptor(UUID())
        else:
            return dialect.type_descriptor(CHAR(32))

    def process_bind_param(self, value, dialect):
        return self.convert_value_to_guid(value, dialect)

    def _uuid_value(self, value):
        if value is None:
            return value
        else:
            if not isinstance(value, uuid.UUID):
                value = uuid.UUID(value)
            return value

    def process_result_value(self, value, dialect):
        return self._uuid_value(value)

    def sort_key_function(self, value):
        return self._uuid_value(value)

from datetime import UTC, datetime

from sqlalchemy.types import DateTime, TypeDecorator


def get_utc_now():
    """
    Returns the current time in UTC.
    """
    return datetime.now(UTC)


def get_utc_today():
    """
    Returns the current date in UTC.
    """
    return datetime.now(UTC).date()


class NaiveDateTime(TypeDecorator):
    """
    Mealie uses naive date times since the app handles timezones explicitly.
    All timezones are generated, stored, and retrieved as UTC.

    This class strips the timezone from a datetime object when storing it so the database (i.e. postgres)
    doesn't do any timezone conversion when storing the datetime, then re-inserts UTC when retrieving it.
    """

    impl = DateTime
    cache_ok = True

    def process_bind_param(self, value: datetime | None, dialect):
        if value is None:
            return value

        try:
            if value.tzinfo is not None:
                value = value.astimezone(UTC)
            return value.replace(tzinfo=None)
        except Exception:
            return value

    def process_result_value(self, value: datetime | None, dialect):
        try:
            if value is not None:
                value = value.replace(tzinfo=UTC)
        except Exception:
            pass

        return value

